function f({registerIndicator:c,sourceValues:n,sma:u,nulls:p}){c({id:"oa-quantileloss",name:"Quantile Loss (Pinball Loss)",category:"Errors",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:5e3,step:1},{key:"quantile",type:"number",label:"Quantile",default:.5,min:.01,max:.99,step:.05,tooltip:"0.5 is the median (mean absolute error). Above 0.5 penalises under-prediction, below 0.5 penalises over-prediction."},{key:"actual",type:"source",label:"Actual",default:"close"},{key:"predicted",type:"source",label:"Predicted",default:"open"}],plots:[{key:"loss",type:"line",title:"Quantile Loss",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(t,l){const d=Math.max(1,Math.floor(Number(l.length)||14)),o=Math.min(.99,Math.max(.01,Number(l.quantile)||.5)),i=n(t,l.actual??"close"),s=n(t,l.predicted??"open"),r=new Array(t.length).fill(NaN);for(let e=0;e<t.length;e++){const m=Number.isFinite(i[e])?i[e]:0,b=Number.isFinite(s[e])?s[e]:0,a=m-b;r[e]=a>=0?o*a:(o-1)*a}return{loss:p(u(r,d))}}})}export{f as default};
